    KnowledgeArticle = apps.get_model("knowledge", "KnowledgeArticle")
    existing_slugs = set()

    def build_unique_slug(title):
        base_slug = slugify(title) or "article"
        slug = base_slug
        index = 1
        while slug in existing_slugs:
            index += 1
            slug = f"{base_slug}-{index}"
        existing_slugs.add(slug)
        return slug

